// swiftlint:disable file_length
import Foundation

/// Pre-graded puzzles, used when generation cannot find a puzzle of the requested level in time
/// (CODESPEC 2.2: no silent fallback) and as practice drills by technique (CODESPEC 13.5).
/// Generated offline with this app's generator and LogicalSolver (seeds 20261101 and, for the five
/// levels, 20261103), so no licence applies. Givens then added back to each level's target with
/// docs/audit/bundled-add-back.swift (seed 20261113). 120 per level, then drill-only lines: the
/// original minimal boards of puzzles that lost a technique in add-back.
/// Each line: level|initial grid|solution|score|techniques[|drill].
enum BundledPuzzles { // swiftlint:disable:this type_body_length
    struct Entry: Equatable {
        let difficulty: Difficulty
        let initialGrid: String
        let solutionGrid: String
        let score: Int
        let techniques: [Technique]
        /// A drill only: outside the level's target givens, never offered as a level puzzle.
        var isDrillOnly = false
    }

    static let all: [Entry] = data.split(separator: "\n").compactMap { line in
        let fields = line.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
        guard fields.count == 5 || fields.count == 6, let score = Int(fields[3]) else { return nil }
        guard let difficulty = Difficulty(rawValue: fields[0]) else { return nil }
        let techniques = fields[4].split(separator: ",").compactMap { Technique(rawValue: String($0)) }
        return Entry(difficulty: difficulty, initialGrid: fields[1], solutionGrid: fields[2], score: score,
                     techniques: techniques, isDrillOnly: fields.count == 6)
    }

    static func puzzles(for difficulty: Difficulty) -> [Entry] {
        all.filter { $0.difficulty == difficulty && !$0.isDrillOnly }
    }

    /// Practice puzzles that need the given technique, easiest first.
    static func drills(for technique: Technique) -> [Entry] {
        all.filter { $0.techniques.contains(technique) }.sorted { $0.score < $1.score }
    }

